import{bV as d,aL as e,u as o,G as r}from"./chunks/framework.ExNI9tDi.js";const g=JSON.parse('{"title":"模块简介","description":"","frontmatter":{"date":"2026-08-06T22:22:34.000Z","title":"模块简介","permalink":"/pages/opencv","categories":["接口"]},"headers":[],"relativePath":"01.接口/50.OpenCV/01.模块简介.md","filePath":"01.接口/50.OpenCV/01.模块简介.md","lastUpdated":null}'),a={name:"01.接口/50.OpenCV/01.模块简介.md"};function c(i,t,n,h,l,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="模块简介" tabindex="-1">模块简介 <a class="header-anchor" href="#模块简介" aria-label="Permalink to &quot;模块简介&quot;">​</a></h1><h2 id="模块简介-1" tabindex="-1">模块简介 <a class="header-anchor" href="#模块简介-1" aria-label="Permalink to &quot;模块简介&quot;">​</a></h2><p><code>OpencvOps</code> 提供常用图像预处理能力。</p><ul><li><strong>系统要求</strong>：Android 7.0+（minSdk 24）</li></ul><h2 id="功能概览" tabindex="-1">功能概览 <a class="header-anchor" href="#功能概览" aria-label="Permalink to &quot;功能概览&quot;">​</a></h2><ul><li><strong>统一转换</strong>：<code>bitmapToMat(bitmap)</code> —— Bitmap 转 Mat 句柄（入口）</li><li><strong>读取文件</strong>：<code>readResMat(path)</code> —— 从图片文件读取为 Mat</li><li><strong>尺寸查询</strong>：<code>getWidth(matId)</code> / <code>getHeight(matId)</code> —— 获取 Mat 宽高</li><li><strong>灰度处理</strong>：<code>matToGray(matId)</code> —— 彩色图转单通道灰度图</li><li><strong>二值化处理</strong>：<code>matThreshold(matId, thresh, maxval, type)</code> —— 固定阈值二值化</li><li><strong>双阈值二值化</strong>：<code>matDoubleThreshold(matId, lowThresh, highThresh, maxval)</code> —— 区间保留二值化</li><li><strong>自适应二值化</strong>：<code>matAdaptiveThreshold(matId, maxValue, adaptiveMethod, thresholdType, blockSize, c)</code> —— 局部自适应二值化</li><li><strong>颜色空间转换</strong>：<code>getHSV(matId, type)</code> / <code>getHLS(matId, type)</code> / <code>getBGR(matId, type)</code> —— 全图或单通道</li><li><strong>像素平均值</strong>：<code>getBGRAverage(matId, type)</code> —— 获取 BGR 各通道像素平均值</li><li><strong>边缘检测</strong>：<code>findCannys(matId, threshold1, threshold2, apertureSize, L2gradient)</code> —— Canny 边缘检测</li><li><strong>形状检测</strong>：<code>findLines</code> / <code>findCircles</code> / <code>findPolygons</code>（二值图轻量入口）/ <code>findPolygonsEx</code>（任意图增强入口） —— 直线 / 圆 / 凸包形状检测</li><li><strong>凸包</strong>：<code>getConvexHull</code> / <code>isContourConvex</code></li><li><strong>轮廓处理</strong>：<code>getContours</code> / <code>getContoursRect</code> / <code>getContoursCircles</code> / <code>getContoursLength</code> / <code>getContoursArea</code> / <code>getContoursHierarchy</code> / <code>getContoursMoments</code></li><li><strong>形态学操作</strong>：<code>dilate</code> / <code>erode</code> / <code>open</code> / <code>close</code> / <code>topHat</code> / <code>blackHat</code> / <code>gradient</code> / <code>skeleton</code></li><li><strong>滤波 / 像素运算</strong>：<code>absDiff</code> / <code>bitwiseOr</code> / <code>medianBlur</code> / <code>gaussianBlur</code> / <code>blur</code> / <code>bilateral</code> / <code>filter2D</code></li><li><strong>颜色范围 / 掩膜</strong>：<code>inRange</code> / <code>copyTo</code></li><li><strong>区域操作</strong>：<code>cropMat</code>（裁剪） / <code>drawRect</code> / <code>drawRects</code>（画框） / <code>findImg</code>（模板匹配找图）</li><li><strong>梯度形状匹配</strong>：<code>loadYaml</code> / <code>matchGradientShape</code> / <code>releaseYaml</code> / <code>getYamlNames</code></li><li><strong>几何变换</strong>：<code>warpPerspective</code>（透视变换）</li><li><strong>投影与计数</strong>：<code>projection</code> / <code>projectionValue</code>（行 / 列投影）/ <code>projectionMean</code>（行 / 列平均亮度）/ <code>countNonZero</code> / <code>countNonZeroRect</code>（非零像素计数）</li><li><strong>保存</strong>：<code>saveMat(matId, path)</code> —— Mat 句柄保存为图片文件（自动创建父目录）</li><li><strong>回收</strong>：<code>recycle(matId)</code> / <code>clearMats()</code> —— 释放 Mat 池内存</li><li><strong>回收校验</strong>：<code>isRecycled(matId)</code> —— 判断 Mat 句柄是否已回收</li></ul><h2 id="接口清单" tabindex="-1">接口清单 <a class="header-anchor" href="#接口清单" aria-label="Permalink to &quot;接口清单&quot;">​</a></h2><h3 id="基础-句柄管理" tabindex="-1">基础 / 句柄管理 <a class="header-anchor" href="#基础-句柄管理" aria-label="Permalink to &quot;基础 / 句柄管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>bitmapToMat(bitmap)</code></td><td>String</td><td>Bitmap 转 Mat 句柄（入口）</td></tr><tr><td><code>matToBitmap(matId)</code></td><td>Bitmap</td><td>Mat 句柄转 Bitmap</td></tr><tr><td><code>readResMat(path)</code></td><td>String</td><td>从图片文件读取为 Mat 句柄</td></tr><tr><td><code>getWidth(matId)</code></td><td>Int</td><td>获取 Mat 宽度</td></tr><tr><td><code>getHeight(matId)</code></td><td>Int</td><td>获取 Mat 高度</td></tr><tr><td><code>getMatInfo(matId)</code></td><td>String</td><td>获取 Mat 的尺寸/通道/类型等基础信息 JSON</td></tr><tr><td><code>getMatCount()</code></td><td>Int</td><td>获取 Mat 池当前句柄数量</td></tr><tr><td><code>saveMat(matId, path)</code></td><td>Boolean</td><td>Mat 句柄保存为图片文件（自动创建父目录）</td></tr><tr><td><code>recycle(matId)</code></td><td>Boolean</td><td>释放单个 Mat 句柄</td></tr><tr><td><code>isRecycled(matId)</code></td><td>Boolean</td><td>判断 Mat 句柄是否已回收</td></tr><tr><td><code>clearMats()</code></td><td>Int</td><td>清空 Mat 池并返回释放数量</td></tr></tbody></table><h3 id="图像转换与二值化" tabindex="-1">图像转换与二值化 <a class="header-anchor" href="#图像转换与二值化" aria-label="Permalink to &quot;图像转换与二值化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>matToGray(matId)</code></td><td>String</td><td>彩色图转单通道灰度图</td></tr><tr><td><code>matThreshold(matId, thresh, maxval, type)</code></td><td>String</td><td>固定阈值二值化</td></tr><tr><td><code>matDoubleThreshold(matId, lowThresh, highThresh, maxval)</code></td><td>String</td><td>区间保留二值化</td></tr><tr><td><code>matAdaptiveThreshold(matId, maxValue, adaptiveMethod, thresholdType, blockSize, c)</code></td><td>String</td><td>局部自适应二值化</td></tr></tbody></table><h3 id="颜色空间" tabindex="-1">颜色空间 <a class="header-anchor" href="#颜色空间" aria-label="Permalink to &quot;颜色空间&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>getHSV(matId, type)</code></td><td>String</td><td>全图或单通道转 HSV</td></tr><tr><td><code>getHLS(matId, type)</code></td><td>String</td><td>全图或单通道转 HLS</td></tr><tr><td><code>getBGR(matId, type)</code></td><td>String</td><td>全图或单通道转 BGR</td></tr><tr><td><code>getBGRAverage(matId, type)</code></td><td>Any</td><td>获取 BGR 各通道像素平均值</td></tr><tr><td><code>inRange(matId, lower, upper)</code></td><td>String</td><td>颜色范围提取，输出单通道二值掩膜</td></tr><tr><td><code>copyTo(matId, mask)</code></td><td>String</td><td>按掩膜复制图片，mask 为空复制原图</td></tr></tbody></table><h3 id="边缘-形状检测" tabindex="-1">边缘 / 形状检测 <a class="header-anchor" href="#边缘-形状检测" aria-label="Permalink to &quot;边缘 / 形状检测&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>findCannys(matId, threshold1, threshold2, apertureSize, L2gradient)</code></td><td>String</td><td>Canny 边缘检测</td></tr><tr><td><code>findLines(matId, src_multiple, rho, theta, threshold, minLineLength, maxLineGap, weakThreshold, strongThreshold)</code></td><td>String</td><td>HoughLinesP 直线检测</td></tr><tr><td><code>findCircles(matId, minDist, accuracy, minRadius, maxRadius, cannyThreshold, dp)</code></td><td>String</td><td>HoughCircles 圆形检测</td></tr><tr><td><code>findPolygons(matId, edgeCount, compareMode, retrievalMode, approxMode, minArea, maxArea, approxEpsilon, scoreThreshold)</code></td><td>String</td><td>二值图轻量多边形检测</td></tr><tr><td><code>findPolygonsEx(matId, edgeCount, compareMode, retrievalMode, approxMode, minArea, maxArea, approxEpsilon, scoreThreshold)</code></td><td>String</td><td>任意图增强多边形检测</td></tr></tbody></table><h3 id="凸包" tabindex="-1">凸包 <a class="header-anchor" href="#凸包" aria-label="Permalink to &quot;凸包&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>getConvexHull(matId, mode, method, contoursIndex, thickness, lineType)</code></td><td>String</td><td>绘制轮廓凸包</td></tr><tr><td><code>isContourConvex(matId, mode, method, contoursIndex, epsilon)</code></td><td>String</td><td>判断轮廓是否为凸包，返回布尔数组</td></tr></tbody></table><h3 id="轮廓处理" tabindex="-1">轮廓处理 <a class="header-anchor" href="#轮廓处理" aria-label="Permalink to &quot;轮廓处理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>getContours(matId, mode, method, contoursIndex, thickness, lineType)</code></td><td>String</td><td>轮廓提取并绘制到画布</td></tr><tr><td><code>getContoursRect(matId, mode, method, contoursIndex)</code></td><td>String</td><td>轮廓外接矩形（left/top/right/bottom/width/height/fill）</td></tr><tr><td><code>getContoursCircles(matId, mode, method, contoursIndex)</code></td><td>String</td><td>轮廓最小外接圆 [[x,y,r],...]</td></tr><tr><td><code>getContoursLength(matId, mode, method, contoursIndex)</code></td><td>String</td><td>轮廓周长数组</td></tr><tr><td><code>getContoursArea(matId, mode, method, contoursIndex)</code></td><td>String</td><td>轮廓面积数组</td></tr><tr><td><code>getContoursMoments(matId, mode, method, contoursIndex)</code></td><td>String</td><td>轮廓重心 [[cx,cy],...]</td></tr><tr><td><code>getContoursHierarchy(matId, mode, method)</code></td><td>String</td><td>轮廓拓扑层级信息</td></tr></tbody></table><h3 id="形态学操作" tabindex="-1">形态学操作 <a class="header-anchor" href="#形态学操作" aria-label="Permalink to &quot;形态学操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>dilate(matId, structType, structWidth, structHeight, anchorX, anchorY, iterations)</code></td><td>String</td><td>膨胀</td></tr><tr><td><code>erode(matId, structType, structWidth, structHeight, anchorX, anchorY, iterations)</code></td><td>String</td><td>腐蚀</td></tr><tr><td><code>open(matId, structType, structWidth, structHeight, anchorX, anchorY, iterations)</code></td><td>String</td><td>开操作，去除小噪点</td></tr><tr><td><code>close(matId, structType, structWidth, structHeight, anchorX, anchorY, iterations)</code></td><td>String</td><td>闭操作，填充小孔</td></tr><tr><td><code>topHat(matId, structType, structWidth, structHeight, anchorX, anchorY, iterations)</code></td><td>String</td><td>顶帽，提取比邻域亮的部分</td></tr><tr><td><code>blackHat(matId, structType, structWidth, structHeight, anchorX, anchorY, iterations)</code></td><td>String</td><td>黑帽，提取比邻域暗的部分</td></tr><tr><td><code>gradient(matId, structType, structWidth, structHeight, anchorX, anchorY, iterations)</code></td><td>String</td><td>梯度，提取图像边界</td></tr><tr><td><code>skeleton(matId, maxIterations)</code></td><td>String</td><td>骨架提取，二值图细化为单像素宽</td></tr></tbody></table><h3 id="滤波-像素运算" tabindex="-1">滤波 / 像素运算 <a class="header-anchor" href="#滤波-像素运算" aria-label="Permalink to &quot;滤波 / 像素运算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>absDiff(matId1, matId2)</code></td><td>String</td><td>两图逐像素绝对差（帧差法）</td></tr><tr><td><code>bitwiseOr(matId1, matId2)</code></td><td>String</td><td>两图按位或（合并掩膜）</td></tr><tr><td><code>medianBlur(matId, ksize)</code></td><td>String</td><td>中值模糊（去椒盐噪声）</td></tr><tr><td><code>gaussianBlur(matId, kSize, sigmaX, sigmaY, borderType)</code></td><td>String</td><td>高斯模糊（保边去噪）</td></tr><tr><td><code>blur(matId, ksize_width, ksize_height, anchorX, anchorY, borderType)</code></td><td>String</td><td>均值模糊</td></tr><tr><td><code>bilateral(matId, d, sigmaColor, sigmaSpace, borderType)</code></td><td>String</td><td>双边滤波（保边去噪）</td></tr><tr><td><code>filter2D(matId, kernelType, ddepth, anchorX, anchorY, delta, borderType)</code></td><td>String</td><td>锐化 / 内置卷积核滤波</td></tr></tbody></table><h3 id="区域操作-几何变换" tabindex="-1">区域操作 / 几何变换 <a class="header-anchor" href="#区域操作-几何变换" aria-label="Permalink to &quot;区域操作 / 几何变换&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>cropMat(matId, left, top, right, bottom)</code></td><td>String</td><td>裁剪 Mat 区域</td></tr><tr><td><code>resizeMat(matId, width, height, interpolation)</code></td><td>String</td><td>缩放图片，宽高任一为 0 时按比例自动计算</td></tr><tr><td><code>drawRect(matId, left, top, right, bottom, color, thickness, dashed, antiAliased)</code></td><td>String</td><td>绘制单个矩形框</td></tr><tr><td><code>drawRects(matId, rectsJson, color, thickness, dashed, antiAliased)</code></td><td>String</td><td>批量绘制多个矩形框</td></tr><tr><td><code>findImg(matId, templateMat, x1, y1, x2, y2, maxCount, precision)</code></td><td>String</td><td>模板匹配找图（TM_CCOEFF_NORMED）</td></tr><tr><td><code>warpPerspective(matId, srcPoint, dstPoint, width, height)</code></td><td>String</td><td>透视变换，矫正目标</td></tr></tbody></table><h3 id="投影-计数" tabindex="-1">投影 / 计数 <a class="header-anchor" href="#投影-计数" aria-label="Permalink to &quot;投影 / 计数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>projection(matId, direction)</code></td><td>String</td><td>二值图行 / 列投影图</td></tr><tr><td><code>projectionValue(matId, direction)</code></td><td>String</td><td>每列或每行非零点数量 JSON 数组</td></tr><tr><td><code>projectionMean(matId, direction)</code></td><td>String</td><td>每列或每行像素平均值 JSON 数组（亮度突变边界检测）</td></tr><tr><td><code>countNonZero(matId)</code></td><td>Int</td><td>非零像素数量</td></tr><tr><td><code>countNonZeroRect(matId, left, top, right, bottom)</code></td><td>Int</td><td>指定矩形区域非零像素数量</td></tr></tbody></table><h3 id="梯度形状匹配-yaml" tabindex="-1">梯度形状匹配（YAML） <a class="header-anchor" href="#梯度形状匹配-yaml" aria-label="Permalink to &quot;梯度形状匹配（YAML）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>返回</th><th>说明</th></tr></thead><tbody><tr><td><code>loadYaml(yamlDirOrFile)</code></td><td>String</td><td>加载一个或多个 YAML</td></tr><tr><td><code>releaseYaml(yamlNames)</code></td><td>Boolean</td><td>释放已预加载的 YAML，空串释放全部</td></tr><tr><td><code>getYamlNames()</code></td><td>String</td><td>获取已预加载的 YAML 名称列表</td></tr><tr><td><code>matchGradientShape(matId, yamlNames, x1, y1, x2, y2, threshold, count, pyramidMode, nms)</code></td><td>String</td><td>在 Mat 池图片上用预加载 YAML 做梯度匹配</td></tr></tbody></table><h3 id="返回约定" tabindex="-1">返回约定 <a class="header-anchor" href="#返回约定" aria-label="Permalink to &quot;返回约定&quot;">​</a></h3><ul><li>返回 <code>String</code> 的匹配类接口返回 JSON 字符串，成功时 <code>code</code> 为 <code>0</code>。</li><li>返回 <code>String</code> 的句柄类接口失败时返回 <code>&quot;&quot;</code>，成功时返回形如 <code>mat_1</code> 的 Mat 句柄。</li><li>返回 <code>Int</code> 的计数类接口失败时返回 <code>-1</code>。</li></ul>',31)])])}const u=d(a,[["render",c]]);export{g as __pageData,u as default};
